class Account:
    # 保存剩余可下载次数。
    def __init__(self, remaining):
        self.remaining = remaining

    # 保存成功消耗一次额度，失败抛出保存异常。
    def download(self, save):
        if self.remaining <= 0:
            return False
        self.remaining -= 1
        save()
        return True


def retry_download(account, save):
    return account.download(save)


def display_name():
    return "下载"

