# 依输入顺序返回本次调用可见的文档，保留重复项并跳过无权限或缺失项。
def list_documents(store, tenant, ids):
    result = []
    for item_id in ids:
        rows = store.fetch_documents(tenant, [item_id])
        if rows:
            result.append(rows[0])
    return result

