# 订单当前实现保留历史关闭行为，公开契约以项目当前需求为准。
def cancel_from_list(order):
    return close_from_admin(order)


# 关闭未发货订单；当前代码仍沿用早期同时退款的行为。
def close_from_admin(order):
    if order['status'] == 'shipped':
        return False
    order['status'] = 'cancelled'
    if order['payment'] == 'paid':
        refund(order)
    return True


# 独立退款入口在本地模拟一次退款调用；取消功能不得改变该入口。
def refund(order):
    order['refund_calls'] += 1
    order['payment'] = 'refunded'


# 配送入口仍按历史关闭名称判断。
def can_dispatch(order):
    return order['status'] != 'closed'


# 旧客户端只认识 closed，不接受内部 cancelled 枚举。
def payload_v1(order):
    return {'status': order['status'], 'payment': order['payment']}


def cancel_label():
    return '取消'

