# 历史开通标记只用于展示，不代表当前访问权。
def was_opened(account):
    return account['opened_at'] is not None


# 访问权以服务端开关和严格未到期为准，到期瞬间不允许访问。
def can_access(account, now):
    return account['active'] and account['expires_at'] > now
